policies.inbound:





            authorize rejected before redirect





                text/plain; charset=utf-8


                no-store

            @("The sign-in request was rejected (" + (string)context.Variables["azError"] + "). Contact your administrator.")



<set-variable name="azScope" value="@{
    var q = context.Request.Url.Query;
    var map = new Dictionary(StringComparer.Ordinal);
    foreach (var entry in "{{mcp-resource-scope-map}}".Split(';'))
    {
        var parts = entry.Split('|');
        if (parts.Length == 2) { map[parts[0].Trim()] = parts[1].Trim(); }
    }
    var resource = q.GetValueOrDefault("resource", "");
    if (resource != "")
    {
        return map.ContainsKey(resource) ? map[resource] : "";
    }
    var requested = q.GetValueOrDefault("scope", "");
    foreach (var s in requested.Split(' '))
    {
        if (map.ContainsValue(s)) { return s; }
    }
    return "{{mcp-default-scope}}";
}" />



            authorize rejected: unknown resource




                application/json


                no-store

            {"error":"invalid_target","error_description":"The requested resource is not served by this gateway."}




    authorize redirected to identity provider






        no-store


        @{
            var q = context.Request.Url.Query;
            var amp = "\u0026";
            var parts = new List();
            foreach (var name in new[] { "client_id", "response_type", "redirect_uri" })
            {
                parts.Add(name + "=" + Uri.EscapeDataString(q.GetValueOrDefault(name, "")));
            }
            parts.Add("scope=" + Uri.EscapeDataString((string)context.Variables["azScope"] + " offline_access"));
            foreach (var name in new[] { "state", "code_challenge", "code_challenge_method", "prompt", "login_hint" })
            {
                var value = q.GetValueOrDefault(name, "");
                if (value != "") { parts.Add(name + "=" + Uri.EscapeDataString(value)); }
            }
            return "{{mcp-idp-authority}}/oauth2/v2.0/authorize?" + string.Join(amp, parts);
        }
